<?php

declare(strict_types=1);

namespace App\Shared\Translation;

use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\Routing\Exception\RouteNotFoundException;
use Symfony\Component\Routing\Generator\UrlGeneratorInterface;

/**
 * The hreflang alternates of the current page (SEO-6): one `<locale>-CH` entry per enabled
 * locale that has a path for the page's canonical route, plus `x-default` pointing at the
 * default locale's URL. Routes not declared in the localized form (technical routes, error
 * pages) get none. URLs are generated by route name, never from the route collection.
 */
final readonly class HreflangAlternates
{
    public function __construct(
        private UrlGeneratorInterface $urlGenerator,
        private EnabledLocale $enabledLocale,
    ) {
    }

    /**
     * @param array<string, mixed> $query extra parameters, e.g. ['page' => 2]
     *
     * @return list<HreflangAlternate>
     */
    public function forRequest(Request $request, array $query = []): array
    {
        // The matcher puts the canonical name of a localized route into `_route` and its
        // `_locale` default into `_route_params`; `_canonical_route` is not kept on the request.
        $canonical = $request->attributes->get('_route');
        $params = $request->attributes->get('_route_params', []);
        if (!\is_string($canonical) || '' === $canonical || !\is_array($params) || !\is_string($params['_locale'] ?? null)) {
            return [];
        }
        unset($params['_locale'], $params['_canonical_route']);

        $alternates = [];
        $defaultUrl = null;
        foreach ($this->enabledLocale->all() as $locale) {
            try {
                $url = $this->urlGenerator->generate(
                    $canonical,
                    ['_locale' => $locale] + $params + $query,
                    UrlGeneratorInterface::ABSOLUTE_URL,
                );
            } catch (RouteNotFoundException) {
                continue;
            }

            $alternates[] = new HreflangAlternate($locale.'-CH', $url);
            if ($locale === $this->enabledLocale->default()) {
                $defaultUrl = $url;
            }
        }

        if (null !== $defaultUrl) {
            $alternates[] = new HreflangAlternate('x-default', $defaultUrl);
        }

        return $alternates;
    }
}
